-- Supabase Dashboard > SQL Editor > run all.
create extension if not exists pgcrypto;
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text not null default '',role text not null default 'customer' check(role in('customer','admin')),created_at timestamptz not null default now());
create table if not exists public.products(id uuid primary key default gen_random_uuid(),name text not null,category text not null check(category in('Women','Men','Kids','Shoes','Bags','Beauty','Accessories')),price numeric(10,2) not null default 0 check(price>=0),old_price numeric(10,2) not null default 0,label text not null default '',description text not null default '',image_url text not null,stock integer not null default 0,featured boolean not null default false,active boolean not null default true,created_at timestamptz not null default now());
create table if not exists public.product_variants(id uuid primary key default gen_random_uuid(),product_id uuid not null references public.products(id) on delete cascade,color text not null,image_url text not null,images jsonb not null default '[]',sizes jsonb not null default '[]');
create table if not exists public.orders(id uuid primary key default gen_random_uuid(),customer_id uuid not null references auth.users(id),customer_name text not null,phone text not null,address text not null,city text not null,state text not null,pincode text not null,items jsonb not null,total numeric(10,2) not null,payment_method text not null default 'COD',status text not null default 'Order Placed',created_at timestamptz not null default now());
alter table public.profiles enable row level security;alter table public.products enable row level security;alter table public.product_variants enable row level security;alter table public.orders enable row level security;
create policy "profile read own" on public.profiles for select to authenticated using(id=auth.uid());
create policy "public active products" on public.products for select to anon,authenticated using(active=true or exists(select 1 from public.profiles where id=auth.uid() and role='admin'));
create policy "admin products" on public.products for all to authenticated using(exists(select 1 from public.profiles where id=auth.uid() and role='admin')) with check(exists(select 1 from public.profiles where id=auth.uid() and role='admin'));
create policy "public variants" on public.product_variants for select to anon,authenticated using(exists(select 1 from public.products p where p.id=product_id and p.active=true) or exists(select 1 from public.profiles where id=auth.uid() and role='admin'));
create policy "admin variants" on public.product_variants for all to authenticated using(exists(select 1 from public.profiles where id=auth.uid() and role='admin')) with check(exists(select 1 from public.profiles where id=auth.uid() and role='admin'));
create policy "read own orders" on public.orders for select to authenticated using(customer_id=auth.uid() or exists(select 1 from public.profiles where id=auth.uid() and role='admin'));
create policy "create own orders" on public.orders for insert to authenticated with check(customer_id=auth.uid());
create or replace function public.new_profile() returns trigger language plpgsql security definer set search_path=public as $$begin insert into public.profiles(id,full_name) values(new.id,coalesce(new.raw_user_meta_data->>'full_name','')) on conflict(id) do nothing;return new;end;$$;
drop trigger if exists auth_user_profile on auth.users;create trigger auth_user_profile after insert on auth.users for each row execute procedure public.new_profile();
